import React from 'react';
import {
  LinImageUpload,
  type LinImageUploadApi,
  type LinImageUploadItem,
} from '@linm-soft-org/linm-web-common-components';
import { filesEndpoint } from '../../services/files/endpoint';
import { createGuestFilesClient } from '../../services/incidentPublicReports/guestFiles';
import { useAppToast } from '../../hooks/useAppToast';
import {
  scykPublicReportImageUploadConfig,
  scykPublicReportImageUploadLabels,
} from '../../config/scykPublicReportImageUpload';
import {
  attachmentsToUploadItems,
  resolveUploadDisplayName,
  type IncidentUploadItem,
} from '../MedicalIncidentFormPage/components/IncidentDocumentsTab';
import type { MedicalIncidentAttachment } from '../../models/MedicalIncident';

export type PublicReportUploadItem = IncidentUploadItem;
export { attachmentsToUploadItems, resolveUploadDisplayName };

export function toPublicReportAttachmentDtos(
  items: PublicReportUploadItem[],
): MedicalIncidentAttachment[] {
  return items
    .filter((item) => item.status === 'committed' && item.attachmentId)
    .map((item, index) => ({
      attachmentId: item.attachmentId!,
      objectKey: item.objectKey || '',
      fileName: resolveUploadDisplayName(item),
      contentType: item.contentType,
      sizeBytes: item.sizeBytes,
      sortOrder: index,
    }));
}

export interface PublicReportPhotosSectionProps {
  companyCode?: string;
  guest?: boolean;
  entityId?: string;
  items: LinImageUploadItem[];
  onChange?: (items: LinImageUploadItem[]) => void;
  disabled?: boolean;
  title: string;
}

export const PublicReportPhotosSection: React.FC<PublicReportPhotosSectionProps> = ({
  companyCode = '',
  guest = false,
  entityId,
  items,
  onChange,
  disabled = false,
  title,
}) => {
  const toast = useAppToast();
  const fileErrorMessage = (err: unknown): string => (
    err instanceof Error && err.message
      ? err.message
      : scykPublicReportImageUploadLabels.objectMissing
  );

  const client: LinImageUploadApi = guest
    ? createGuestFilesClient(companyCode)
    : {
        init: filesEndpoint.init,
        complete: filesEndpoint.complete,
        abort: filesEndpoint.abort,
        getObject: filesEndpoint.getObject,
      };

  const withToast: LinImageUploadApi = {
    init: client.init,
    abort: client.abort,
    complete: async (uploadId, objectKey) => {
      try {
        await client.complete?.(uploadId, objectKey);
      } catch (err) {
        toast.error(fileErrorMessage(err));
        throw err;
      }
    },
    getObject: async (attachmentId: string) => {
      try {
        const fetchObject = client.getObject;
        if (!fetchObject) {
          throw new Error(scykPublicReportImageUploadLabels.objectMissing);
        }
        return await fetchObject(attachmentId);
      } catch (err) {
        toast.error(fileErrorMessage(err));
        throw err;
      }
    },
  };

  return (
    <div data-testid="incident-public-report-section-photos">
      <h3>{title}</h3>
      <LinImageUpload
        purpose={scykPublicReportImageUploadConfig.purpose}
        product={scykPublicReportImageUploadConfig.product}
        entityType={scykPublicReportImageUploadConfig.entityType}
        entityId={entityId}
        items={items}
        onChange={onChange ?? (() => undefined)}
        minFiles={scykPublicReportImageUploadConfig.minFiles}
        maxFiles={scykPublicReportImageUploadConfig.maxFiles}
        maxBytes={scykPublicReportImageUploadConfig.maxBytes}
        accept={scykPublicReportImageUploadConfig.accept}
        disabled={disabled}
        confirmRemove={!disabled}
        showModalActions={false}
        labels={scykPublicReportImageUploadLabels}
        client={withToast}
        testId="incident-public-report-field-photos"
      />
    </div>
  );
};
